// =============================================================================
//  cam_preview.v — 摄像头实时预览（抽降采样 → 片内帧缓存 → 放大显示）
//  工程: f9p_ph1p100_imx415x2      器件: PH1P100SBG484 / -3
// -----------------------------------------------------------------------------
//  数据流
//    采集侧（CSI-2 字节时钟域 187.5MHz，I_pix_data 每拍 4 个 10bit 像素）
//        源 3840x2160 RAW10
//          水平: 每 DEC_CYC 拍取 1 拍，用该拍前 2 个像素求平均   --> SW 列
//          垂直: 每 DEC_LINE 个源行成一组，取组内前 2 行平均     --> SH 行
//        ==> SW x SH 灰度（8bit）写入帧缓存
//    显示侧（HDMI 像素时钟域 137.5MHz）
//        每 SCALE x SCALE 个显示像素读同一源像素（最近邻放大）-> H_ACT x V_ACT
//
//  参数约束（改分辨率必须同时满足；下面 initial 里会检查）
//    SW = 3840 / (DEC_CYC * 4)    每拍 4 像素，每 DEC_CYC 拍出 1 个采样
//    SH = 2160 / DEC_LINE
//    H_ACT % SW == 0              SCALE 必须是整数
//    当前: SW=960, SH=540, DEC_LINE=4, DEC_CYC=1, SCALE=2 → 输出 1920x1080
//
//  依赖与约束
//    · 帧缓存用 reg 数组，但写口必须是"单时钟 + 单条 if (we) mem[a] <= d"的简单形式 ——
//      这样 TD 才会把它推断成 ERAM20K 硬块（实测 u_cam_preview 占 203 块 / 上限 300，
//      LUT6 只有百余个）。写成带复位的复杂形式会被判成分布式 RAM（LUT），
//      几万字节就能把器件撑爆（曾出现 slice 65664 > 25600 的失败）。
//    · I_frame 上升沿复位列/行计数，保证每帧取到同一批源行（防垂直滚动）。
//    · 读写地址都用"行基址增量相加"，不放乘法在关键路径上。
//    · 跨时钟域只过 O_cam_alive 一个标志（2 级同步器 ASYNC_REG），像素数据靠帧缓存。
//    · 帧缓存拆成 4 个 bank（每 bank 只装 SH/4 行）：整帧 518KB 让 TD 映射成 ~191 个 ERAM 块后，
//      块间地址译码 + 读出多路选择各要 4 级 LUT 加长布线，137.5MHz（7.27ns）压不住（实测 -0.31ns）。
//      分成 4 个各约 51 块的 bank 后，每个 bank 内部选择器浅一级，读侧再加一个 4:1 选择，时序收敛。
// =============================================================================
`timescale 1ns / 1ps

module cam_preview_capture #(
    // ---- 抽降后（帧缓存）分辨率 ----
    parameter SW         = 960,          // 抽降后宽（源 3840）
    parameter SH         = 540,          // 抽降后高（源 2160）
    // ---- 显示有效区 ----
    parameter H_ACT      = 1920,
    parameter V_ACT      = 1080,
    // ---- 抽降比 ----
    parameter DEC_LINE   = 4,            // 每 DEC_LINE 个源行成一组（2160/4 = 540）
    parameter DEC_CYC    = 1,            // 每 DEC_CYC 个字节拍取 1 个采样（960/1 = 960）
    // ---- 采集活动检测 ----
    parameter ALIVE_BITS = 24            // 超过 2^ALIVE_BITS 个字节时钟无行脉冲 → 判为无数据
)(
    // ---------------- 采集侧：CSI-2 字节时钟域 ----------------
    input  wire          I_bc_clk,
    input  wire          I_bc_rst_n,
    input  wire [39:0]   I_pix_data,     // 4 个 10bit 像素（每拍）
    input  wire          I_pix_valid,    // 该拍像素有效
    input  wire          I_line,         // 行脉冲（每行一个）
    input  wire          I_frame,        // 帧内标志（上升沿同步计数器）

    // ---------------- 显示侧：像素时钟域 ----------------
    input  wire          I_pclk,
    input  wire          I_pclk_rst_n,
    input  wire          I_de,           // 显示数据有效
    input  wire          I_vs,           // 帧同步
    output wire [23:0]   O_rgb,          // 灰度输出 {Y,Y,Y}
    output wire          O_de,           // 与 O_rgb 对齐
    output wire O_gray_sof,O_gray_valid,O_gray_last,output wire[7:0] O_gray_data,
    output wire          O_cam_alive     // 采集侧有活动（已同步到像素时钟域）
);

    // -------------------------------------------------------------------------
    // 派生参数
    // -------------------------------------------------------------------------
    function integer clog2b;                     // ceil(log2(x))，x<=1 时返回 1
        input integer x;
        integer i;
        begin
            clog2b = 1;
            for (i = 2; i < x; i = i * 2) clog2b = clog2b + 1;
        end
    endfunction

    localparam NBANK  = 4;                       // 帧缓存 bank 数（见头部说明）
    localparam RPB    = SH / NBANK;              // 每个 bank 的行数
    localparam AWB    = clog2b(RPB * SW);        // bank 内地址位宽
    localparam RAM_DEPTH = (1 << AWB); // complete address space for ERAM
    localparam SCALE  = H_ACT / SW;              // 放大倍数（须整除）
    localparam LPH_W  = clog2b(DEC_LINE);        // 组内行相位计数器位宽
    localparam CYC_W  = clog2b(DEC_CYC);         // 字节拍相位计数器位宽
    localparam SWX_W  = clog2b(SCALE);           // 显示侧子像素计数器位宽
    localparam PH_WRT = (DEC_LINE >= 2) ? 1 : 0; // 组内"写出"相位：取前两行平均则写在相位 1

    initial begin
        if (SH % NBANK != 0)          $display("cam_preview: SH 必须能被 bank 数整除");
        if (SW * DEC_CYC * 4 != 3840) $display("cam_preview: SW/DEC_CYC 与源宽 3840 不匹配");
        if (SH * DEC_LINE    != 2160) $display("cam_preview: SH/DEC_LINE 与源高 2160 不匹配");
        if (H_ACT % SW       != 0)    $display("cam_preview: H_ACT 不是 SW 的整数倍");
    end

    // =========================================================================
    // 1. 采集侧（字节时钟域）
    // =========================================================================
    reg  [LPH_W-1:0] r_line_ph  = DEC_LINE[LPH_W-1:0] - 1'b1; // 组内源行相位（0..DEC_LINE-1）
    reg  [CYC_W-1:0] r_cyc_ph   = {CYC_W{1'b0}}; // 字节拍相位（0..DEC_CYC-1）
    reg  [9:0]       r_col      = 10'd0;         // 抽降后列号
    reg  [9:0]       r_rowb     = 10'd0;         // 当前 bank 内行号
    reg  [1:0]       r_bankw    = 2'd0;          // 写入 bank
    reg  [AWB-1:0]   r_wbase    = {AWB{1'b0}};   // bank 内行基址（增量维护）
    reg  [7:0]       r_line_buf [0:SW-1];        // 组内第 1 行的水平平均值
    reg              r_line_d   = 1'b0;
    reg              r_frame_d  = 1'b0;

    reg  [AWB-1:0]   r_wr_addr  = {AWB{1'b0}};
    reg  [7:0]       r_wr_data  = 8'd0;
    reg  [3:0]       r_we       = 4'b0000;       // 每个 bank 一个写使能（与地址/数据同拍寄存）

    (* ram_style = "bram" *) reg  [7:0] r_fb0 [0:RAM_DEPTH-1];               // 帧缓存 4 个 bank（推断为 ERAM20K）
    (* ram_style = "bram" *) reg  [7:0] r_fb1 [0:RAM_DEPTH-1];
    (* ram_style = "bram" *) reg  [7:0] r_fb2 [0:RAM_DEPTH-1];
    (* ram_style = "bram" *) reg  [7:0] r_fb3 [0:RAM_DEPTH-1];

    wire w_line_rise  = I_line  & ~r_line_d;
    wire w_frame_rise = I_frame & ~r_frame_d;

    // 水平平均：取该拍的前两个像素（相邻两列），10bit 求和后取高 8 位
    wire [10:0] w_hsum = {1'b0, I_pix_data[9:0]} + {1'b0, I_pix_data[19:10]};
    wire [7:0]  w_havg = w_hsum[10:3];

    wire w_sample_now = (r_cyc_ph == {CYC_W{1'b0}});
    wire w_store_ph   = (r_line_ph == {LPH_W{1'b0}});          // 组内第 1 行 → 存行缓存
    wire w_write_ph   = (r_line_ph == PH_WRT[LPH_W-1:0]);      // 组内第 2 行 → 平均后写出

    // 帧缓存写口：每个 bank 单独一块，保持"单时钟 + 单条 if"的简单形式，TD 才会映射到 ERAM
    always @(posedge I_bc_clk) if (r_we[0]) r_fb0[r_wr_addr] <= r_wr_data;
    always @(posedge I_bc_clk) if (r_we[1]) r_fb1[r_wr_addr] <= r_wr_data;
    always @(posedge I_bc_clk) if (r_we[2]) r_fb2[r_wr_addr] <= r_wr_data;
    always @(posedge I_bc_clk) if (r_we[3]) r_fb3[r_wr_addr] <= r_wr_data;

    always @(posedge I_bc_clk or negedge I_bc_rst_n) begin
        if (!I_bc_rst_n) begin
            r_line_ph  <= DEC_LINE[LPH_W-1:0] - 1'b1;
            r_cyc_ph   <= {CYC_W{1'b0}};
            r_col      <= 10'd0;
            r_rowb     <= 10'd0;
            r_bankw    <= 2'd0;
            r_wbase    <= {AWB{1'b0}};
            r_line_d   <= 1'b0;
            r_frame_d  <= 1'b0;
            r_we       <= 4'b0000;
        end else begin
            r_line_d  <= I_line;
            r_frame_d <= I_frame;
            r_we      <= 4'b0000;

            // 帧起始：列/行/bank 计数归零，保证每帧取到同一批源行
            if (w_frame_rise) begin
                // First line-start selects store phase 0, not write phase 1.
                r_line_ph <= w_line_rise ? {LPH_W{1'b0}} : DEC_LINE[LPH_W-1:0] - 1'b1;
                r_cyc_ph <= {CYC_W{1'b0}};
                r_col   <= 10'd0;
                r_rowb  <= 10'd0;
                r_bankw <= 2'd0;
                r_wbase <= {AWB{1'b0}};
            end

            // 行脉冲：推进组内相位；一组的最后一个行脉冲之后回到相位 0（下一组开始）
            if (w_line_rise && !w_frame_rise) begin
                r_line_ph <= (r_line_ph == DEC_LINE[LPH_W-1:0] - 1'b1) ? {LPH_W{1'b0}}
                                                                       : r_line_ph + 1'b1;
                r_col     <= 10'd0;
                r_cyc_ph  <= {CYC_W{1'b0}};
            end

            // 像素采样：每 DEC_CYC 个字节拍取 1 个
            if (I_pix_valid && !w_frame_rise) begin
                if (r_cyc_ph == DEC_CYC[CYC_W-1:0] - 1'b1) r_cyc_ph <= {CYC_W{1'b0}};
                else                                       r_cyc_ph <= r_cyc_ph + 1'b1;

                if (w_sample_now && (r_col < SW)) begin
                    if (w_store_ph) begin
                        r_line_buf[r_col] <= w_havg;                       // 组内第 1 行
                    end
                    if (w_write_ph) begin
                        r_wr_data <= (DEC_LINE == 1) ? w_havg              // 单行组：直接写
                                                     : (({1'b0, r_line_buf[r_col]} + {1'b0, w_havg}) >> 1);
                        r_wr_addr <= r_wbase + r_col;
                        r_we      <= (4'b0001 << r_bankw);                 // 只使能当前 bank
                    end

                    r_col <= r_col + 1'b1;
                    if (r_col == SW - 1) begin                             // 一行采完
                        if (w_write_ph) begin                              // 只有写出去了才换目标行
                            if (r_rowb == RPB - 1) begin
                                r_rowb  <= 10'd0;                          // 本 bank 满 → 下一 bank
                                r_wbase <= {AWB{1'b0}};
                                r_bankw <= r_bankw + 1'b1;                 // 2bit 自动回绕
                            end else begin
                                r_rowb  <= r_rowb + 1'b1;
                                r_wbase <= r_wbase + SW[AWB-1:0];
                            end
                        end
                    end
                end
            end
        end
    end

    // 采集活动检测（字节域）：行脉冲超时未到 → 显示侧回落测试图
    reg [ALIVE_BITS-1:0] r_alive_cnt = {ALIVE_BITS{1'b0}};
    reg                  r_alive_bc  = 1'b1;

    always @(posedge I_bc_clk or negedge I_bc_rst_n) begin
        if (!I_bc_rst_n) begin
            r_alive_cnt <= {ALIVE_BITS{1'b0}};
            r_alive_bc  <= 1'b1;
        end else if (w_line_rise) begin
            r_alive_cnt <= {ALIVE_BITS{1'b0}};
            r_alive_bc  <= 1'b1;
        end else if (&r_alive_cnt) begin
            r_alive_bc  <= 1'b0;
        end else begin
            r_alive_cnt <= r_alive_cnt + 1'b1;
        end
    end

    (* ASYNC_REG = "TRUE" *) reg [1:0] r_alive_sync = 2'b00;
    always @(posedge I_pclk) r_alive_sync <= {r_alive_sync[0], r_alive_bc};
    assign O_cam_alive = r_alive_sync[1];

    // =========================================================================
    // 2. 显示侧（像素时钟域）：SCALE 倍最近邻放大
    // =========================================================================
    reg [SWX_W-1:0] r_sx6 = {SWX_W{1'b0}};       // 水平子像素计数（0..SCALE-1）
    reg [SWX_W-1:0] r_sy6 = {SWX_W{1'b0}};       // 垂直子行计数
    reg [9:0]       r_sx    = 10'd0;             // 源列
    reg [9:0]       r_syb   = 10'd0;             // 源行（bank 内）
    reg [1:0]       r_bankr = 2'd0;              // 读 bank
    reg [AWB-1:0]   r_rsbase = {AWB{1'b0}};      // bank 内行基址（增量维护）
    reg [AWB-1:0]   r_raddr = {AWB{1'b0}};       // bank 内读地址
    reg [1:0]       r_rbank = 2'd0;              // 与读地址同拍寄存的 bank 号

    always @(posedge I_pclk or negedge I_pclk_rst_n) begin
        if (!I_pclk_rst_n) begin
            r_sx6 <= {SWX_W{1'b0}}; r_sy6 <= {SWX_W{1'b0}};
            r_sx  <= 10'd0;         r_syb <= 10'd0;   r_bankr <= 2'd0;
            r_rsbase <= {AWB{1'b0}};
        end else if (I_vs) begin
            r_sx6 <= {SWX_W{1'b0}}; r_sy6 <= {SWX_W{1'b0}};
            r_sx  <= 10'd0;         r_syb <= 10'd0;   r_bankr <= 2'd0;
            r_rsbase <= {AWB{1'b0}};
        end else if (I_de) begin
            if (r_sx6 == SCALE[SWX_W-1:0] - 1'b1) begin
                r_sx6 <= {SWX_W{1'b0}};
                if (r_sx == SW - 1) begin
                    r_sx <= 10'd0;
                    if (r_sy6 == SCALE[SWX_W-1:0] - 1'b1) begin
                        r_sy6 <= {SWX_W{1'b0}};
                        if (r_syb == RPB - 1) begin
                            r_syb    <= 10'd0;             // 本 bank 读完 → 下一 bank
                            r_rsbase <= {AWB{1'b0}};
                            r_bankr  <= r_bankr + 1'b1;    // 2bit 自动回绕
                        end else begin
                            r_syb    <= r_syb + 1'b1;
                            r_rsbase <= r_rsbase + SW[AWB-1:0];
                        end
                    end else begin
                        r_sy6 <= r_sy6 + 1'b1;
                    end
                end else begin
                    r_sx <= r_sx + 1'b1;
                end
            end else begin
                r_sx6 <= r_sx6 + 1'b1;
            end
        end
    end

    always @(posedge I_pclk) begin
        r_raddr <= r_rsbase + r_sx;
        r_rbank <= r_bankr;
    end

    // Explicit synchronous read on each RAM before the bank mux.
    // Full address-space arrays above avoid the failed non-power-of-two mapping.
    // Preserve the existing address->data latency and bank selection cycle.
    reg [7:0] r_rd0, r_rd1, r_rd2, r_rd3;
    reg [1:0] r_rd_bank = 2'd0;
    always @(posedge I_pclk) begin
        r_rd0 <= r_fb0[r_raddr];
        r_rd1 <= r_fb1[r_raddr];
        r_rd2 <= r_fb2[r_raddr];
        r_rd3 <= r_fb3[r_raddr];
        r_rd_bank <= r_rbank;
    end
    wire [7:0] r_rd_data = (r_rd_bank == 2'd0) ? r_rd0 :
                           (r_rd_bank == 2'd1) ? r_rd1 :
                           (r_rd_bank == 2'd2) ? r_rd2 : r_rd3;

    // Address register + synchronous RAM read: delay DE through both stages.
    reg [1:0] r_de_d = 2'b00;
    always @(posedge I_pclk or negedge I_pclk_rst_n) begin
        if (!I_pclk_rst_n) r_de_d <= 2'b00;
        else               r_de_d <= {r_de_d[0], I_de};
    end
    assign O_de = r_de_d[1];

    assign O_rgb = {r_rd_data, r_rd_data, r_rd_data};

// Tap the same registered word that is written into the original preview RAM.
assign O_gray_sof=w_frame_rise;
assign O_gray_valid=(|r_we)&&!w_frame_rise;
assign O_gray_data=r_wr_data;
assign O_gray_last=O_gray_valid&&r_we[3]&&(r_wr_addr==RPB*SW-1);
endmodule

`timescale 1ns/1ps
module camera_ddr_capture #(parameter FRAME_BYTES=518400,FIFO_BITS=8)(
 input clk,cap_clk,rst_n,ddr_ready,sof,pixel_valid,pixel_last,input[7:0] pixel,
 output[31:0] passed_frames,failed_frames,published_frames,protocol_errors,capture_drops,
 output[26:0] paxi_awaddr,output paxi_awvalid,input paxi_awready,
 output[255:0] paxi_wdata,output[31:0] paxi_wstrb,output paxi_wvalid,paxi_wlast,input paxi_wready,
 output[26:0] paxi_araddr,output paxi_arvalid,input paxi_arready,
 input[255:0] paxi_rdata,input paxi_rvalid,paxi_rlast,output paxi_rready
);
 (* async_reg="true" *) reg[1:0] cap_reset,usr_reset;
 always @(posedge cap_clk or negedge rst_n)if(!rst_n)cap_reset<=0;else cap_reset<={cap_reset[0],1'b1};
 always @(posedge clk or negedge rst_n)if(!rst_n)usr_reset<=0;else usr_reset<={usr_reset[0],1'b1};
 wire[257:0] token_in,fifo_token;wire token_write,token_space,fifo_valid,token_take;
 reg[257:0] token;reg token_valid;
 wire fifo_take=!token_valid;
 gray_frame_pack #(.FRAME_BYTES(FRAME_BYTES)) u_pack(.clk(cap_clk),.rst_n(cap_reset[1]),.sof(sof),.pixel_valid(pixel_valid),.pixel_last(pixel_last),.pixel(pixel),.out_data(token_in),.out_valid(token_write),.out_ready(token_space),.dropped_frames(capture_drops));
 capture_async_fifo #(.WIDTH(258),.ADDR_BITS(FIFO_BITS)) u_fifo(.rst_n(rst_n),.wclk(cap_clk),.w_valid(token_write),.w_data(token_in),.w_ready(token_space),.rclk(clk),.r_valid(fifo_valid),.r_data(fifo_token),.r_ready(fifo_take));
 // One-word staging cuts consumer decode/ready -> FIFO ERAM read-enable timing.
 // Deliberate bubble: maximum 100M tokens/s at 200MHz, far above this preview.
 always @(posedge clk)if(!token_valid&&fifo_valid)token<=fifo_token;
 always @(posedge clk or negedge rst_n)begin
  if(!rst_n)token_valid<=0;
  else if(!usr_reset[1]||!ddr_ready)token_valid<=0;
  else if(!token_valid&&fifo_valid)token_valid<=1;
  else if(token_valid&&token_take)token_valid<=0;
 end
 wire[1:0] tag=token[257:256];reg in_frame;
 wire begin_ready,data_ready;
 wire begin_frame=token_valid&&(tag==1)&&!in_frame&&ddr_ready;
 wire abort_frame=token_valid&&((tag==3)||((tag==1)&&in_frame));
 wire data_valid=token_valid&&((tag==0)||(tag==2))&&in_frame&&ddr_ready;
 assign token_take=!ddr_ready?1'b1:
  (tag==1)?(!in_frame&&begin_ready):
  (tag==3)?1'b1:(!in_frame||data_ready);
 always @(posedge clk or negedge rst_n)begin
  if(!rst_n)in_frame<=0;
  else if(!usr_reset[1]||!ddr_ready)in_frame<=0;
  else if(abort_frame)in_frame<=0;
  else if(begin_frame&&begin_ready)in_frame<=1;
  else if(data_valid&&data_ready&&tag==2)in_frame<=0;
 end
 wire frame_switch,frame_switch_ready,frame_valid,rd_req,rd_req_ready,rd_valid,rd_take;
 wire[31:0] read_frame_id,backend_drops;wire[15:0] rd_offset;wire[255:0] rd_data;
 ddr_frame_store #(.FRAME_WORDS(FRAME_BYTES/32+1)) u_store(
  .clk(clk),.rst_n(usr_reset[1]),.ddr_ready(ddr_ready),
  .frame_begin(begin_frame),.frame_id(token[31:0]),.frame_begin_ready(begin_ready),
  .s_data(token[255:0]),.s_valid(data_valid),.s_last(tag==2),.s_abort(abort_frame),.s_ready(data_ready),
  .frame_switch(frame_switch),.frame_switch_ready(frame_switch_ready),.frame_valid(frame_valid),.read_frame_id(read_frame_id),
  .rd_req(rd_req),.rd_offset(rd_offset),.rd_req_ready(rd_req_ready),.rd_data(rd_data),.rd_valid(rd_valid),.rd_take(rd_take),
  .published_count(published_frames),.error_count(protocol_errors),.drop_count(backend_drops),
  .paxi_awaddr(paxi_awaddr),.paxi_awvalid(paxi_awvalid),.paxi_awready(paxi_awready),
  .paxi_wdata(paxi_wdata),.paxi_wstrb(paxi_wstrb),.paxi_wvalid(paxi_wvalid),.paxi_wlast(paxi_wlast),.paxi_wready(paxi_wready),
  .paxi_araddr(paxi_araddr),.paxi_arvalid(paxi_arvalid),.paxi_arready(paxi_arready),
  .paxi_rdata(paxi_rdata),.paxi_rvalid(paxi_rvalid),.paxi_rlast(paxi_rlast),.paxi_rready(paxi_rready));
 ddr_capture_check #(.FRAME_BYTES(FRAME_BYTES)) u_check(
  .clk(clk),.rst_n(usr_reset[1]),.ddr_ready(ddr_ready),.frame_switch(frame_switch),.frame_switch_ready(frame_switch_ready),.frame_valid(frame_valid),.read_frame_id(read_frame_id),
  .rd_req(rd_req),.rd_offset(rd_offset),.rd_req_ready(rd_req_ready),.rd_data(rd_data),.rd_valid(rd_valid),.rd_take(rd_take),.passed_frames(passed_frames),.failed_frames(failed_frames));
endmodule

`timescale 1ns/1ps
// Common asynchronous assertion, independent synchronous release. Registered
// read prefetch permits inferred dual-clock RAM and holds data under backpressure.
module capture_async_fifo #(parameter WIDTH=258,ADDR_BITS=8)(
 input rst_n,wclk,w_valid,input[WIDTH-1:0] w_data,output w_ready,
 input rclk,output reg r_valid,output reg[WIDTH-1:0] r_data,input r_ready
);
 (* async_reg="true" *) reg[1:0] wr_reset,rd_reset;
 always @(posedge wclk or negedge rst_n)if(!rst_n)wr_reset<=0;else wr_reset<={wr_reset[0],1'b1};
 always @(posedge rclk or negedge rst_n)if(!rst_n)rd_reset<=0;else rd_reset<={rd_reset[0],1'b1};
 (* ram_style="bram" *) reg[WIDTH-1:0] mem[0:(1<<ADDR_BITS)-1];
 reg[ADDR_BITS:0] wbin,rbin;reg full;
 // SWUG106 section 4.3.6: retain registered Gray outputs across PHY optimization.
 (* dont_touch="true" *) reg[ADDR_BITS:0] wgray,rgray;
 (* async_reg="true" *) reg[ADDR_BITS:0] rq1_wgray,rq2_wgray,wq1_rgray,wq2_rgray;
 wire push=w_valid&&w_ready;
 wire[ADDR_BITS:0] wn=wbin+push,wgn=(wn>>1)^wn;
 wire empty=(rgray==rq2_wgray);
 wire fetch=rd_reset[1]&&!empty&&(!r_valid||r_ready);
 wire[ADDR_BITS:0] rn=rbin+fetch,rgn=(rn>>1)^rn;
 assign w_ready=wr_reset[1]&&!full;
 always @(posedge wclk)if(push)mem[wbin[ADDR_BITS-1:0]]<=w_data;
 always @(posedge rclk)if(fetch)r_data<=mem[rbin[ADDR_BITS-1:0]];
 always @(posedge wclk or negedge rst_n)begin
  if(!rst_n)begin wbin<=0;wgray<=0;full<=0;wq1_rgray<=0;wq2_rgray<=0;end
  else if(!wr_reset[1])begin wbin<=0;wgray<=0;full<=0;wq1_rgray<=0;wq2_rgray<=0;end
  else begin wq1_rgray<=rgray;wq2_rgray<=wq1_rgray;wbin<=wn;wgray<=wgn;
   full<=(wgn=={~wq2_rgray[ADDR_BITS:ADDR_BITS-1],wq2_rgray[ADDR_BITS-2:0]});end
 end
 always @(posedge rclk or negedge rst_n)begin
  if(!rst_n)begin rbin<=0;rgray<=0;rq1_wgray<=0;rq2_wgray<=0;r_valid<=0;end
  else if(!rd_reset[1])begin rbin<=0;rgray<=0;rq1_wgray<=0;rq2_wgray<=0;r_valid<=0;end
  else begin rq1_wgray<=wgray;rq2_wgray<=rq1_wgray;rbin<=rn;rgray<=rgn;
   if(fetch)r_valid<=1;else if(r_ready)r_valid<=0;end
 end
endmodule

`timescale 1ns/1ps
// Sequential CRC consumes every image byte; footer is checked separately.
module ddr_capture_check #(parameter FRAME_BYTES=518400)(
 input clk,rst_n,ddr_ready,
 output frame_switch,input frame_switch_ready,frame_valid,input[31:0] read_frame_id,
 output rd_req,output reg[15:0] rd_offset,input rd_req_ready,
 input[255:0] rd_data,input rd_valid,output rd_take,
 output reg[31:0] passed_frames,failed_frames
);
 localparam PAYLOAD_WORDS=FRAME_BYTES/32;
 reg[2:0] state;reg[4:0] byte_index;reg[255:0] word_buf;
 reg[31:0] crc,expected_id;reg[4:0] footer_match;
 function[31:0] crc_byte(input[31:0] c,input[7:0] b);
  reg[31:0] v;integer k;begin v=c^b;for(k=0;k<8;k=k+1)v=(v>>1)^(v[0]?32'hedb88320:0);crc_byte=v;end
 endfunction
 assign frame_switch=(state==0)&&ddr_ready;
 assign rd_req=(state==2)&&ddr_ready&&frame_valid;
 assign rd_take=(state==3)&&rd_valid;
 always @(posedge clk or negedge rst_n)begin
  if(!rst_n)begin state<=0;rd_offset<=0;byte_index<=0;word_buf<=0;crc<=32'hffffffff;expected_id<=0;footer_match<=0;passed_frames<=0;failed_frames<=0;end
  else if(!ddr_ready||((state!=0)&&(state!=1)&&!frame_valid))begin state<=0;rd_offset<=0;crc<=32'hffffffff;end
  else case(state)
   0:begin crc<=32'hffffffff;rd_offset<=0;if(frame_switch_ready)state<=1;end
   1:begin expected_id<=read_frame_id;state<=2;end
   2:if(rd_req_ready)state<=3;
   3:if(rd_valid)begin
    if(rd_offset==PAYLOAD_WORDS)begin
     footer_match[0]<=(rd_data[31:0]==32'h43524331);
     footer_match[1]<=(rd_data[63:32]==expected_id);
     footer_match[2]<=(rd_data[95:64]==~crc);
     footer_match[3]<=(rd_data[127:96]==FRAME_BYTES);
     footer_match[4]<=(rd_data[255:128]==0);state<=5;
    end else begin word_buf<=rd_data;byte_index<=0;state<=4;end
   end
   4:begin
    crc<=crc_byte(crc,word_buf[7:0]);word_buf<={8'd0,word_buf[255:8]};byte_index<=byte_index+1'b1;
    if(byte_index==31)begin rd_offset<=rd_offset+1'b1;state<=2;end
   end
   5:begin
    if(footer_match===5'b11111)passed_frames<=passed_frames+1'b1;
    else failed_frames<=failed_frames+1'b1;
    state<=0;
   end
   default:state<=0;
  endcase
 end
endmodule

`timescale 1ns/1ps
// Single DDR-user-clock domain. Native PH1P PAXI: one 256-bit command,
// address step 8, mask 0 writes every byte. This is not a standard AXI master.
// Contract: ready loss must flush/reset the controller's pending responses.
// Recovery without that flush needs a controller-specific drain/epoch adapter.
module ddr_frame_store #(parameter FRAME_WORDS=16200)(
 input clk,rst_n,ddr_ready,
 input frame_begin,input [31:0] frame_id,output frame_begin_ready,
 input [255:0] s_data,input s_valid,s_last,s_abort,output s_ready,
 input frame_switch,output frame_switch_ready,frame_valid,output [31:0] read_frame_id,
 input rd_req,input [15:0] rd_offset,output rd_req_ready,
 output reg [255:0] rd_data,output reg rd_valid,input rd_take,
 output reg [31:0] published_count,error_count,drop_count,
 output [26:0] paxi_awaddr,output paxi_awvalid,input paxi_awready,
 output [255:0] paxi_wdata,output [31:0] paxi_wstrb,output paxi_wvalid,paxi_wlast,input paxi_wready,
 output [26:0] paxi_araddr,output paxi_arvalid,input paxi_arready,
 input [255:0] paxi_rdata,input paxi_rvalid,paxi_rlast,output paxi_rready
);
 localparam FREE=0,WRITING=1,READY=2,READING=3;
 localparam IDLE=0,WRITE=1,FENCE=2,VERIFY=3;
 reg [1:0] slot_state[0:2];reg [31:0] slot_id[0:2];
 reg [1:0] write_slot,read_slot,write_state;
 reg [15:0] write_offset;
 reg read_active,read_outstanding,read_is_fence,write_turn,abort_fence;
 reg [255:0] last_word;
 reg [7:0] fence_match;reg fence_rlast;
 wire has_free=(slot_state[0]==FREE)||(slot_state[1]==FREE)||(slot_state[2]==FREE);
 wire [1:0] free_slot=(slot_state[0]==FREE)?0:(slot_state[1]==FREE)?1:2;
 wire has_ready=(slot_state[0]==READY)||(slot_state[1]==READY)||(slot_state[2]==READY);
 wire [1:0] ready_slot=(slot_state[0]==READY)?0:(slot_state[1]==READY)?1:2;
 function [26:0] base(input [1:0] slot);
   begin case(slot) 0:base=0;1:base=FRAME_WORDS*8;default:base=FRAME_WORDS*16;endcase end
 endfunction
 wire want_fence=(write_state==FENCE)&&!read_outstanding&&!s_abort;
 wire want_read=rd_req&&read_active&&!rd_valid&&!read_outstanding&&!frame_switch&&(rd_offset<FRAME_WORDS);
 wire want_write=(write_state==WRITE)&&s_valid&&!s_abort;
 wire read_choice=want_fence||(want_read&&(!want_write||!write_turn));
 wire write_choice=want_write&&!want_fence&&(!want_read||write_turn);
 wire common_ready=rst_n&&ddr_ready&&paxi_awready&&paxi_arready;
 wire do_read=read_choice&&common_ready;
 wire do_write=write_choice&&common_ready&&paxi_wready;
 assign frame_begin_ready=rst_n&&ddr_ready&&(write_state==IDLE)&&has_free&&!s_abort;
 assign frame_switch_ready=rst_n&&ddr_ready&&has_ready&&!read_outstanding&&!rd_valid&&(write_state!=VERIFY);
 assign frame_valid=rst_n&&ddr_ready&&read_active;
 assign read_frame_id=slot_id[read_slot];
 assign rd_req_ready=do_read&&!want_fence;
 assign s_ready=do_write;
 assign paxi_awaddr=base(write_slot)+{8'd0,write_offset,3'b000};
 assign paxi_awvalid=do_write;
 assign paxi_wdata=s_data;
 assign paxi_wstrb=32'd0;
 assign paxi_wvalid=do_write;
 assign paxi_wlast=1'b1;
 assign paxi_araddr=want_fence?(base(write_slot)+(FRAME_WORDS-1)*8):(base(read_slot)+{8'd0,rd_offset,3'b000});
 assign paxi_arvalid=do_read;
 assign paxi_rready=1'b1;
 integer i;
 always @(posedge clk or negedge rst_n)begin
   if(!rst_n)begin
     for(i=0;i<3;i=i+1)begin slot_state[i]<=FREE;slot_id[i]<=0;end
     write_slot<=0;read_slot<=0;write_state<=IDLE;write_offset<=0;
     read_active<=0;read_outstanding<=0;read_is_fence<=0;write_turn<=1;abort_fence<=0;
     last_word<=0;fence_match<=0;fence_rlast<=0;
     rd_data<=0;rd_valid<=0;published_count<=0;error_count<=0;drop_count<=0;
   end else if(!ddr_ready)begin
     for(i=0;i<3;i=i+1)slot_state[i]<=FREE;
     if(write_state!=IDLE)drop_count<=drop_count+1'b1;
     write_state<=IDLE;write_offset<=0;read_active<=0;read_outstanding<=0;
     rd_valid<=0;abort_fence<=0;write_turn<=1;
   end else begin
     if(rd_valid&&rd_take)rd_valid<=0;
     if(frame_begin&&frame_begin_ready)begin
       write_slot<=free_slot;slot_state[free_slot]<=WRITING;slot_id[free_slot]<=frame_id;
       write_offset<=0;write_state<=WRITE;abort_fence<=0;
     end
     if(frame_switch&&frame_switch_ready)begin
       if(read_active)slot_state[read_slot]<=FREE;
       read_slot<=ready_slot;slot_state[ready_slot]<=READING;read_active<=1;
     end
     if(s_abort&&write_state!=IDLE&&write_state!=VERIFY)begin
       if(write_state==FENCE&&read_outstanding)abort_fence<=1;
       else begin slot_state[write_slot]<=FREE;write_state<=IDLE;drop_count<=drop_count+1'b1;end
     end
     if(do_write)begin
       write_turn<=0;
       if(s_last!=(write_offset==FRAME_WORDS-1))begin
         slot_state[write_slot]<=FREE;write_state<=IDLE;
         error_count<=error_count+1'b1;drop_count<=drop_count+1'b1;
       end else if(s_last)begin last_word<=s_data;write_state<=FENCE;end
       else write_offset<=write_offset+1'b1;
     end
     if(do_read)begin read_outstanding<=1;read_is_fence<=want_fence;write_turn<=1;end
     if(paxi_rvalid&&read_outstanding)begin
       read_outstanding<=0;
       if(read_is_fence)begin
         // Break the 256-bit compare -> ownership/counter path at 200MHz.
         for(i=0;i<8;i=i+1)fence_match[i]<=(paxi_rdata[i*32+:32]===last_word[i*32+:32]);
         fence_rlast<=paxi_rlast;write_state<=VERIFY;
         if(s_abort)abort_fence<=1;
       end else if(paxi_rlast!==1'b1)begin
         error_count<=error_count+1'b1;read_active<=0;slot_state[read_slot]<=FREE;
       end else begin rd_data<=paxi_rdata;rd_valid<=1;end
     end
     if(write_state==VERIFY)begin
       write_state<=IDLE;
       if(abort_fence||s_abort)begin slot_state[write_slot]<=FREE;drop_count<=drop_count+1'b1;end
       else if(fence_rlast!==1'b1||fence_match!==8'hff)begin
         slot_state[write_slot]<=FREE;error_count<=error_count+1'b1;drop_count<=drop_count+1'b1;
       end else begin
         // Newest complete frame replaces only READY, never READING.
         for(i=0;i<3;i=i+1)if(slot_state[i]==READY && !(frame_switch&&frame_switch_ready&&ready_slot==i))slot_state[i]<=FREE;
         slot_state[write_slot]<=READY;published_count<=published_count+1'b1;
       end
     end
   end
 end
endmodule

// Board wrapper derived from vendor ddrmc_test_top.v.
// Preserves DDR IP and initialization APB; replaces the old traffic generator.

`timescale 1ps/1ps


module ddrmc_capture_top #(
    parameter FRAME_BYTES = 518400,
    parameter DX_NUM     = 4 ,
    parameter BA_WIDTH   = 3 ,
    parameter BG_WIDTH   = 0 ,
    parameter ROW_WIDTH  = 14,
    parameter COL_WIDTH  = 10,
    parameter CS_WIDTH   = 1 ,
    parameter CKE_WIDTH  = 1 ,
    parameter ODT_WIDTH  = 1
)(
// clock & reset
    input cap_clk,cap_sof,cap_valid,cap_last,input[7:0] cap_data,
    input                       ref_clk       ,
    input                       sys_rst_n     ,
    output                      cfg_clk       ,
    output                      ddrphy_rst_n  ,

    // APB Interface
    input                       usr_apb_pclk    ,
    input                       usr_apb_preset_n,
    input                       usr_apb_psel    ,
    input                       usr_apb_penable ,
    input                       usr_apb_pwrite  ,
    input     [          31:0]  usr_apb_paddr   ,
    input     [          31:0]  usr_apb_pwdata  ,
    output                      usr_apb_pready  ,
    output    [          31:0]  usr_apb_prdata  ,
// ddrio
    output                      ddr_ck_p      ,
    output                      ddr_ck_n      ,
    output  [        1 -1 : 0]  ddr_reset_n   ,
    output  [CKE_WIDTH-1  : 0]  ddr_cke       ,
    output  [ODT_WIDTH-1  : 0]  ddr_odt       ,
    output  [CS_WIDTH-1   : 0]  ddr_cs_n      ,
    output                      ddr_ras_n     ,
    output                      ddr_cas_n     ,
    output                      ddr_we_n      ,
    output  [BA_WIDTH  -1 : 0]  ddr_ba        ,
    output  [ROW_WIDTH -1 : 0]  ddr_addr      ,
    inout   [DX_NUM    -1 : 0]  ddr_dqs_p     ,
    inout   [DX_NUM    -1 : 0]  ddr_dqs_n     ,
    inout   [DX_NUM  *8-1 : 0]  ddr_dq        ,
    inout   [DX_NUM    -1 : 0]  ddr_dm        ,

// MISC
    output  [2:0]               led
);


///////////////////////////////////////////////////////////////////////////////////////////////////
// Local Parameter Definition
///////////////////////////////////////////////////////////////////////////////////////////////////
localparam APP_ADDR_WIDTH = BG_WIDTH + BA_WIDTH + ROW_WIDTH + COL_WIDTH;
localparam APP_DATA_WIDTH = DX_NUM*64;
localparam APP_MASK_WIDTH = DX_NUM*8;

///////////////////////////////////////////////////////////////////////////////////////////////////
// Logic Signals Definition
///////////////////////////////////////////////////////////////////////////////////////////////////
wire                  dhi_clk      ;
wire                  ddrphy_rdy   ;
(* MARK_DEBUG="true" *) wire [31:0] passed_frames,failed_frames,published_frames,protocol_errors;


// ALC PAXI
wire [APP_ADDR_WIDTH-1:0]  paxi_awaddr        ;
wire                       paxi_awvalid       ;
wire                       paxi_awready       ;
wire [APP_DATA_WIDTH-1:0]  paxi_wdata         ;
wire [APP_MASK_WIDTH-1:0]  paxi_wstrb         ;
wire                       paxi_wvalid        ;
wire                       paxi_wlast         ;
wire                       paxi_wready        ;
wire [APP_ADDR_WIDTH-1:0]  paxi_araddr        ;
wire                       paxi_arvalid       ;
wire                       paxi_arready       ;
wire                       paxi_rlast         ;
wire                       paxi_rvalid        ;
wire                       paxi_rready        ;
wire [APP_DATA_WIDTH-1:0]  paxi_rdata ;
// apb
wire                  ddrphy_apb_pclk    ;
wire                  ddrphy_apb_prst_n  ;
wire                  ddrphy_apb_psel    ;
wire                  ddrphy_apb_penable ;
wire                  ddrphy_apb_pwrite  ;
wire [         15:0]  ddrphy_apb_paddr   ;
wire [         31:0]  ddrphy_apb_pwdata  ;
wire                  ddrphy_apb_pready  ;
wire [         31:0]  ddrphy_apb_prdata  ;

///////////////////////////////////////////////////////////////////////////////////////////////////
//  DDRPHY WRAPPER
///////////////////////////////////////////////////////////////////////////////////////////////////
ddrmc_x32 u_ddrmc_x32 (
    // clock & reset
    .ref_clk         ( ref_clk        ), // input
    .dhi_clk         ( dhi_clk        ), // output
    .cfg_clk         ( cfg_clk        ), // output

    .sys_rst_n       ( sys_rst_n      ), // input
    .ddrphy_rst_n    ( ddrphy_rst_n   ), // output
    .ddrphy_rdy      ( ddrphy_rdy     ),

    // APB
    .apb_pclk        ( ddrphy_apb_pclk    ),
    .apb_prst_n      ( ddrphy_apb_prst_n  ),
    .apb_psel        ( ddrphy_apb_psel    ),
    .apb_penable     ( ddrphy_apb_penable ),
    .apb_pwrite      ( ddrphy_apb_pwrite  ),
    .apb_paddr       ( ddrphy_apb_paddr   ),
    .apb_pwdata      ( ddrphy_apb_pwdata  ),
    .apb_pready      ( ddrphy_apb_pready  ), // output
    .apb_prdata      ( ddrphy_apb_prdata  ), // output

    .paxi_awaddr     ( paxi_awaddr        ),
    .paxi_awvalid    ( paxi_awvalid       ),
    .paxi_awready    ( paxi_awready       ),
    .paxi_wdata      ( paxi_wdata         ),
    .paxi_wstrb      ( paxi_wstrb         ),
    .paxi_wvalid     ( paxi_wvalid        ),
    .paxi_wlast      ( paxi_wlast         ),
    .paxi_wready     ( paxi_wready        ),
    .paxi_araddr     ( paxi_araddr        ),
    .paxi_arvalid    ( paxi_arvalid       ),
    .paxi_arready    ( paxi_arready       ),
    .paxi_rdata      ( paxi_rdata         ),
    .paxi_rlast      ( paxi_rlast         ),
    .paxi_rvalid     ( paxi_rvalid        ),
    .paxi_rready     ( paxi_rready        ),

    // Retain the vendor refresh policy; do not request a manual refresh.
    .usr_ref_type    ( 2'b00              ),
    .usr_ref_req     ( 1'b0               ),

    // ddrio
    .ddr_ck_p        ( ddr_ck_p           ),
    .ddr_ck_n        ( ddr_ck_n           ),
    .ddr_reset_n     ( ddr_reset_n        ),
    .ddr_cke         ( ddr_cke            ),
    .ddr_odt         ( ddr_odt            ),
    .ddr_cs_n        ( ddr_cs_n           ),
    .ddr_ras_n       ( ddr_ras_n          ),
    .ddr_cas_n       ( ddr_cas_n          ),
    .ddr_we_n        ( ddr_we_n           ),
    .ddr_ba          ( ddr_ba             ),
    .ddr_addr        ( ddr_addr           ),
    .ddr_dqs_p       ( ddr_dqs_p          ),
    .ddr_dqs_n       ( ddr_dqs_n          ),
    .ddr_dq          ( ddr_dq             ),
    .ddr_dm          ( ddr_dm             )
);


wire[31:0] capture_drops;
camera_ddr_capture #(.FRAME_BYTES(FRAME_BYTES)) u_capture(
 .clk(dhi_clk),.cap_clk(cap_clk),.rst_n(ddrphy_rst_n),.ddr_ready(ddrphy_rdy),
 .sof(cap_sof),.pixel_valid(cap_valid),.pixel_last(cap_last),.pixel(cap_data),
 .passed_frames(passed_frames),.failed_frames(failed_frames),.published_frames(published_frames),.protocol_errors(protocol_errors),.capture_drops(capture_drops),
 .paxi_awaddr(paxi_awaddr),.paxi_awvalid(paxi_awvalid),.paxi_awready(paxi_awready),
 .paxi_wdata(paxi_wdata),.paxi_wstrb(paxi_wstrb),.paxi_wvalid(paxi_wvalid),.paxi_wlast(paxi_wlast),.paxi_wready(paxi_wready),
 .paxi_araddr(paxi_araddr),.paxi_arvalid(paxi_arvalid),.paxi_arready(paxi_arready),
 .paxi_rdata(paxi_rdata),.paxi_rvalid(paxi_rvalid),.paxi_rlast(paxi_rlast),.paxi_rready(paxi_rready));
reg [25:0] clk_cnt;
reg pass_seen,error_seen;
always @(posedge dhi_clk or negedge ddrphy_rst_n)begin
 if(!ddrphy_rst_n)begin clk_cnt<=0;pass_seen<=0;error_seen<=0;end
 else begin
  clk_cnt<=clk_cnt+1'b1;
  if(passed_frames!=0)pass_seen<=1;
  if(failed_frames!=0||protocol_errors!=0)error_seen<=1;
 end
end
// Active-low LEDs: ready heartbeat, a complete good frame seen, sticky failure.
assign led[0]=~(ddrphy_rdy&&clk_cnt[25]);
assign led[1]=~pass_seen;
assign led[2]=~error_seen;

assign ddrphy_apb_prst_n=usr_apb_preset_n;
assign ddrphy_apb_psel=usr_apb_psel&&(usr_apb_paddr[23:20]==0);
assign ddrphy_apb_penable=usr_apb_penable;
assign ddrphy_apb_pwrite=usr_apb_pwrite;
assign ddrphy_apb_paddr=usr_apb_paddr[15:0];
assign ddrphy_apb_pwdata=usr_apb_pwdata;
// cfg_clk is the APB clock supplied to the board MCU, as in the vendor top.
// Only single-bit diagnostic flags cross; no incoherent multi-bit counter reads.
(* ASYNC_REG="TRUE" *) reg [2:0] flags_meta,flags_sync;
always @(posedge usr_apb_pclk or negedge usr_apb_preset_n)begin
 if(!usr_apb_preset_n)begin flags_meta<=0;flags_sync<=0;end
 else begin flags_meta<={error_seen,pass_seen,ddrphy_rdy};flags_sync<=flags_meta;end
end
reg [31:0] status_rdata;
always @* begin
 case(usr_apb_paddr[7:0])
  8'hf0:status_rdata=32'h46525031; // FRP1, distinct from the old mtest register map
  8'hf4:status_rdata={29'd0,flags_sync}; // bit0 ready, bit1 good-frame seen, bit2 failure
  default:status_rdata=32'hdeadbeef;
 endcase
end
// The old mtest window is intentionally not emulated. Writes have no effect.
assign usr_apb_pready=(usr_apb_paddr[23:20]==0)?ddrphy_apb_pready:1'b1;
assign usr_apb_prdata=(usr_apb_paddr[23:20]==0)?ddrphy_apb_prdata:
 (usr_apb_paddr[23:20]==1)?status_rdata:32'hdeadbeef;
endmodule

// =============================================================================
//  f9p_imx415x2_top.v — MLK-F9P-CA05-PH1P100 + FEP-VID006-MIPI + 2 x IMX415
//  工程: f9p_ph1p100_imx415x2      器件: PH1P100SBG484 / -3      工具: TD 6.2.3
// -----------------------------------------------------------------------------
//  功能
//    · 两路 MIPI CSI-2 接收（自写 PH1P 软 D-PHY + 复用米联客 CSI-2 包层）
//    · 两路独立 I2C 配置 IMX415（4K@30 档），提供传感器 MCLK / XCLR
//    · HDMI 输出：PLL + VTC + 测试图 / 摄像头实时预览（二选一）
//    · 上板遥测：4 个 LED + 115200 UART 状态行（比数灯精确）
//
//  时钟域
//    sys_clk50m  50MHz（H4，1.35V SSTL135）：复位、I2C、遥测
//    byte_clk    111.375MHz：PHY 由 MIPI 时钟 lane 分频得到（两路各自独立）
//    pclkx1      148.5MHz：HDMI 像素时钟（PLL clk0）
//    pclkx5      742.5MHz：HDMI OSERDES 5 倍串行时钟（PLL clk1）
//
//  关键引脚（详见 uisrc/04_pin/fep_vid006_imx415.adc，全部已上板实测）
//    MIPI-A: clk K18/K19  lane0 N20/M20  lane1 K21/K22  lane2 N18/N19  lane3 M21/L21
//    MIPI-B: clk J19/H19  lane0 J22/H22  lane1 G17/G18  lane2 J20/J21  lane3 L19/L20
//    A 口控制: SCL N22  SDA M22  MCLK L18  XCLR M18
//    B 口控制: SCL H13  SDA G13  MCLK G20  XCLR H20
//    注意：MIPI 差分走底板 FEP1B 的 C 排（子卡 A 排那侧串了 100R，会衰减到收不满）
//
//  修订
//    v1.0  2026-10-10  初版：两路 MIPI + I2C + 遥测，上板两路 4K30 满速
//    v1.1  2026-10-10  加 HDMI 输出（测试图）与摄像头预览（320x180 灰度）
// =============================================================================
`timescale 1ns / 1ps

module f9p_camera_capture_core (
    output wire cap_clk,cap_sof,cap_valid,cap_last,output wire[7:0] cap_data,
    input  wire         sys_clk50m,          // 板载 50MHz（H4, 1.35V）

    // ---- MIPI-A（子卡 U5 / FEP1A）----
    input  wire         mipi_a_clk_hs_p,
    input  wire         mipi_a_clk_hs_n,
    input  wire [3:0]   mipi_a_data_hs_p,
    input  wire [3:0]   mipi_a_data_hs_n,
    // ---- MIPI-B（子卡 U6 / FEP1A）----
    input  wire         mipi_b_clk_hs_p,
    input  wire         mipi_b_clk_hs_n,
    input  wire [3:0]   mipi_b_data_hs_p,
    input  wire [3:0]   mipi_b_data_hs_n,

    // ---- 传感器 A 控制（1V8）----
    output wire         cam_a_scl,           // C4  -> N22
    inout  wire         cam_a_sda,           // C5  -> M22
    output wire         cam_a_mclk,          // A5  -> L18
    output wire         cam_a_xclr_n,        // 子卡 A4 (FGPIO 当复位用) -> M18
    // ---- 传感器 B 控制（1V8）----
    output wire         cam_b_scl,           // 子卡 A28 -> H13
    inout  wire         cam_b_sda,           // 子卡 A29 -> G13
    output wire         cam_b_mclk,          // 子卡 C29 -> G20
    output wire         cam_b_xclr_n,        // 子卡 C28 -> H20

    output wire [3:0]   O_led,
    output wire         O_uart_txd,         // FPGA_UART_TX0 = R17，115200 8N1 状态输出

    // ---- HDMI 输出（HDMI-OUT 口：FD0=B15 FD1=B21 FD2=C22 FCLK=C18，3V3 LVDS）----
    output wire         O_hdmi_clk_p,
    output wire [2:0]   O_hdmi_tx_p
);

    // ------------------------------------------------------------------
    // 复位 / 时钟
    // ------------------------------------------------------------------
    reg [15:0] r_pwr_cnt = 16'd0;
    reg        r_rst_n   = 1'b0;
    always @(posedge sys_clk50m) begin
        if (r_pwr_cnt != 16'hFFFF) begin
            r_pwr_cnt <= r_pwr_cnt + 1'b1;
            r_rst_n   <= 1'b0;
        end else begin
            r_rst_n   <= 1'b1;
        end
    end

    wire w_pclkx1,w_pclkx5,w_pll_locked,w_mclk_raw;
    wire w_mclk,w_xclr_n,r_rst_n_slow;
    raw10_display60_clocks X_ui_pll (
        .refclk(sys_clk50m),.reset(~r_rst_n),.lock(w_pll_locked),
        .clk0_out(w_pclkx1),.clk1_out(w_pclkx5),.clk2_out(w_mclk_raw));
    camera_startup u_camera_startup (
        .I_clk(sys_clk50m),.I_pll_locked(w_pll_locked),.I_mclk(w_mclk_raw),
        .O_xclr_n(w_xclr_n),.O_mclk(w_mclk),.O_cfg_rst_n(r_rst_n_slow));
    assign cam_a_mclk=w_mclk;assign cam_b_mclk=w_mclk;
    assign cam_a_xclr_n=w_xclr_n;assign cam_b_xclr_n=w_xclr_n;
    reg [2:0] pixel_reset_sync=0;
    always @(posedge w_pclkx1 or negedge w_pll_locked)
        if(!w_pll_locked) pixel_reset_sync<=0;
        else pixel_reset_sync<={pixel_reset_sync[1:0],1'b1};
    wire w_pixel_rst_n=pixel_reset_sync[2];

    // ------------------------------------------------------------------
    // IDELAY 采样点（tap）：实测眼图中点，见 README「上板踩出来的坑」
    //   tap 45~47 收包率最高；自动扫描（auto_delay_ctl）会回落到复位值 32，只有 1/9 收包率
    //   USE_MANUAL_TAP=0 可切回自动扫描；换板/换线速率需要重新扫（每 2s 换一个 tap 读串口）
    // ------------------------------------------------------------------
    localparam        USE_MANUAL_TAP = 1'b1;
    localparam [5:0]  CAM_IDELAY_TAP = 6'd46;

    // ------------------------------------------------------------------
    // 两路 MIPI CSI-2 接收（PHY 内置字节对齐 + IDELAY 自动扫描）
    // ------------------------------------------------------------------
    wire [5:0]  w_a_delay_tap, w_b_delay_tap;
    wire        w_a_delay_done, w_b_delay_done;
    wire        w_a_byte_clk, w_b_byte_clk;
    wire        w_a_rst_out, w_b_rst_out;
    wire [3:0]  w_a_lane_valid, w_b_lane_valid;
    wire        w_a_sync_wait, w_b_sync_wait;
    wire        w_a_pkt_done, w_b_pkt_done;
    wire        w_a_vsync, w_b_vsync;
    wire        w_a_in_frame, w_b_in_frame;
    wire        w_a_in_line, w_b_in_line;
    wire [39:0] w_a_pixel, w_b_pixel;
    wire        w_a_pixel_valid, w_b_pixel_valid;

    mipi_csi2_rx_ph1p #(.LANE_NUM(4)) u_csi_a (
        .I_ref_clk          (sys_clk50m      ),
        .I_rst_n            (r_rst_n         ),
        .I_rx_en            (r_rst_n         ),
        .I_clk_pad_hs_p     (mipi_a_clk_hs_p ),
        .I_clk_pad_hs_n     (mipi_a_clk_hs_n ),
        .I_data_pad_hs_p    (mipi_a_data_hs_p),
        .I_data_pad_hs_n    (mipi_a_data_hs_n),
        .I_manual_delay     (CAM_IDELAY_TAP),
        .I_manual_en        (USE_MANUAL_TAP),
        .O_byte_clk         (w_a_byte_clk    ),
        .O_rst_out          (w_a_rst_out     ),
        .O_lane_valid       (w_a_lane_valid  ),
        .O_delay_tap        (w_a_delay_tap   ),
        .O_auto_delay_done  (w_a_delay_done  ),
        .O_sync_wait        (w_a_sync_wait   ),
        .O_packet_done      (w_a_pkt_done    ),
        .O_vsync            (w_a_vsync       ),
        .O_in_frame         (w_a_in_frame    ),
        .O_in_line          (w_a_in_line     ),
        .O_pixel_data       (w_a_pixel       ),
        .O_pixel_valid      (w_a_pixel_valid )
    );

    mipi_csi2_rx_ph1p #(.LANE_NUM(4)) u_csi_b (
        .I_ref_clk          (sys_clk50m      ),
        .I_rst_n            (r_rst_n         ),
        .I_rx_en            (r_rst_n         ),
        .I_clk_pad_hs_p     (mipi_b_clk_hs_p ),
        .I_clk_pad_hs_n     (mipi_b_clk_hs_n ),
        .I_data_pad_hs_p    (mipi_b_data_hs_p),
        .I_data_pad_hs_n    (mipi_b_data_hs_n),
        .I_manual_delay     (CAM_IDELAY_TAP),
        .I_manual_en        (USE_MANUAL_TAP),
        .O_byte_clk         (w_b_byte_clk    ),
        .O_rst_out          (w_b_rst_out     ),
        .O_lane_valid       (w_b_lane_valid  ),
        .O_delay_tap        (w_b_delay_tap   ),
        .O_auto_delay_done  (w_b_delay_done  ),
        .O_sync_wait        (w_b_sync_wait   ),
        .O_packet_done      (w_b_pkt_done    ),
        .O_vsync            (w_b_vsync       ),
        .O_in_frame         (w_b_in_frame    ),
        .O_in_line          (w_b_in_line     ),
        .O_pixel_data       (w_b_pixel       ),
        .O_pixel_valid      (w_b_pixel_valid )
    );

    // ------------------------------------------------------------------
    // IMX415 寄存器配置（两路独立 I2C，传感器 I2C 地址相同 0x34(8bit)）
    //   I2C 时钟：50MHz / (CLK_DIV+1) = 100kHz  ->  CLK_DIV = 499
    // ------------------------------------------------------------------
    wire w_a_cfg_done, w_b_cfg_done;
    wire w_a_bus_err,  w_b_bus_err;
    wire w_a_ae_done,  w_b_ae_done;

    ui_cfg_imx415 #(.CLK_DIV(16'd499)) u_cfg_a (
        .I_clk         (sys_clk50m),
        .I_rst_n       (r_rst_n_slow),
        .I_cam_mode    (2'd1),          // 1 = 4K
        .I_ae_req      (1'b0),
        .I_ae_data     (8'd100),
        .O_cam_scl     (cam_a_scl),
        .IO_cam_sda    (cam_a_sda),
        .O_cfg_done    (w_a_cfg_done),
        .O_ae_cfg_done (w_a_ae_done),
        .O_bus_error   (w_a_bus_err)
    );

    ui_cfg_imx415 #(.CLK_DIV(16'd499)) u_cfg_b (
        .I_clk         (sys_clk50m),
        .I_rst_n       (r_rst_n_slow),
        .I_cam_mode    (2'd1),          // 1 = 4K
        .I_ae_req      (1'b0),
        .I_ae_data     (8'd100),
        .O_cam_scl     (cam_b_scl),
        .IO_cam_sda    (cam_b_sda),
        .O_cfg_done    (w_b_cfg_done),
        .O_ae_cfg_done (w_b_ae_done),
        .O_bus_error   (w_b_bus_err)
    );

    // ------------------------------------------------------------------
    // 状态指示（LED1~4）与 UART 状态输出（115200，R17）
    // ------------------------------------------------------------------
    reg r_any_pkt = 1'b0;
    always @(posedge sys_clk50m)
        if (w_a_pkt_done | w_b_pkt_done) r_any_pkt <= 1'b1;

    reg [3:0] r_led = 4'd0;
    always @(posedge sys_clk50m) begin
        r_led[0] <= w_a_cfg_done;                 // A 口 I2C 配置完成
        r_led[1] <= w_b_cfg_done;                 // B 口 I2C 配置完成
        r_led[2] <= w_a_bus_err | w_b_bus_err;    // 任一口 I2C NACK
        r_led[3] <= r_any_pkt;                    // 收到过 CSI-2 包（真出图了）
    end

    assign O_led = r_led;

    // 字节域脉冲 → 翻转电平（跨到 50MHz 域安全计数）
    wire w_a_pkt_tgl, w_a_vs_tgl, w_b_pkt_tgl, w_b_vs_tgl;
    wire w_a_clk_tgl, w_b_clk_tgl;

    // 字节时钟活动（每 2^15 个字节时钟翻转一次）
    clk_activity #(.DIV_BITS(15)) u_a_clk_act (.I_clk(w_a_byte_clk), .I_rst_n(w_a_rst_out), .O_tgl(w_a_clk_tgl));
    clk_activity #(.DIV_BITS(15)) u_b_clk_act (.I_clk(w_b_byte_clk), .I_rst_n(w_b_rst_out), .O_tgl(w_b_clk_tgl));

    // 每 lane 字节对齐粘滞标志（哪几条 lane 曾经对齐过）
    reg [3:0] r_a_lane_sticky = 4'd0, r_b_lane_sticky = 4'd0;
    always @(posedge sys_clk50m) begin
        r_a_lane_sticky <= r_a_lane_sticky | w_a_lane_valid;
        r_b_lane_sticky <= r_b_lane_sticky | w_b_lane_valid;
    end

    // I2C NACK 锁存 + 计数（bus_error 是瞬时信号，0.5s 采一次会漏掉）
    reg r_a_err_lat = 1'b0, r_b_err_lat = 1'b0;
    reg [31:0] r_a_nack_cnt = 32'd0, r_b_nack_cnt = 32'd0;
    always @(posedge sys_clk50m) begin
        if (w_a_bus_err) begin r_a_err_lat <= 1'b1; r_a_nack_cnt <= r_a_nack_cnt + 1'b1; end
        if (w_b_bus_err) begin r_b_err_lat <= 1'b1; r_b_nack_cnt <= r_b_nack_cnt + 1'b1; end
    end

    pulse2toggle u_tgl_apkt (.I_clk(w_a_byte_clk), .I_rst_n(w_a_rst_out), .I_pulse(w_a_pkt_done), .O_tgl(w_a_pkt_tgl));
    pulse2toggle u_tgl_avs  (.I_clk(w_a_byte_clk), .I_rst_n(w_a_rst_out), .I_pulse(w_a_vsync   ), .O_tgl(w_a_vs_tgl ));
    pulse2toggle u_tgl_bpkt (.I_clk(w_b_byte_clk), .I_rst_n(w_b_rst_out), .I_pulse(w_b_pkt_done), .O_tgl(w_b_pkt_tgl));
    pulse2toggle u_tgl_bvs  (.I_clk(w_b_byte_clk), .I_rst_n(w_b_rst_out), .I_pulse(w_b_vsync   ), .O_tgl(w_b_vs_tgl ));

    dbg_uart #(
        .CLK_DIV (16'd434)
    ) u_dbg_uart (
        .I_clk          (sys_clk50m     ),
        .I_rst_n        (r_rst_n        ),
        .I_a_lane_valid (w_a_lane_valid ),
        .I_a_tap        (w_a_delay_tap  ),
        .I_a_cfg_done   (w_a_cfg_done   ),
        .I_a_bus_err    (r_a_err_lat    ),
        .I_a_pkt_tgl    (w_a_pkt_tgl    ),
        .I_a_vs_tgl     (w_a_vs_tgl     ),
        .I_a_clk_tgl    (w_a_clk_tgl    ),
        .I_a_nack_cnt   (r_a_nack_cnt   ),
        .I_a_lane_sticky(r_a_lane_sticky),
        .I_b_lane_sticky(r_b_lane_sticky),
        .I_b_nack_cnt   (r_b_nack_cnt   ),
        .I_b_lane_valid (w_b_lane_valid ),
        .I_b_tap        (w_b_delay_tap  ),
        .I_b_cfg_done   (w_b_cfg_done   ),
        .I_b_bus_err    (r_b_err_lat    ),
        .I_b_pkt_tgl    (w_b_pkt_tgl    ),
        .I_b_vs_tgl     (w_b_vs_tgl     ),
        .I_b_clk_tgl    (w_b_clk_tgl    ),
        .O_txd          (O_uart_txd     )
    );

    // ------------------------------------------------------------------
    // HDMI: 148.5 MHz pixel / 742.5 MHz native serializer; 2200 x 1125, 60 Hz.
    wire w_vtc_vs,w_vtc_hs,w_vtc_de,w_vtc_user,w_vtc_last;
    wire [7:0] w_rgb_r,w_rgb_g,w_rgb_b;

    uivtc #(
        .H_ActiveSize (1920), .H_SyncStart (1920+88), .H_SyncEnd (1920+88+44), .H_FrameSize (1920+88+44+148),
        .V_ActiveSize (1080), .V_SyncStart (1080+4),  .V_SyncEnd (1080+4+5),  .V_FrameSize (1080+4+5+36)
    ) X_uivtc (
        .I_vtc_clk      (w_pclkx1),
        .I_vtc_rstn     (w_pixel_rst_n),
        .O_vtc_vs       (w_vtc_vs),
        .O_vtc_hs       (w_vtc_hs),
        .O_vtc_de_valid (w_vtc_de),
        .O_vtc_user     (w_vtc_user),
        .O_vtc_last     (w_vtc_last)
    );

    wire [23:0] w_tpg_rgb, w_cam_rgb;
    wire        w_cam_de, w_cam_alive;
    // Match camera address-register + synchronous RAM-read latency.
    reg [1:0] r_cam_hs = 0, r_cam_vs = 0;
    always @(posedge w_pclkx1) begin
        if (!w_pixel_rst_n) begin r_cam_hs <= 0; r_cam_vs <= 0; end
        else begin
            r_cam_hs <= {r_cam_hs[0], w_vtc_hs};
            r_cam_vs <= {r_cam_vs[0], w_vtc_vs};
        end
    end

    reg r_tpg_hs=0,r_tpg_vs=0,r_tpg_de=0;
    always @(posedge w_pclkx1) begin
        if(!w_pixel_rst_n) begin r_tpg_hs<=0;r_tpg_vs<=0;r_tpg_de<=0;end
        else begin r_tpg_hs<=w_vtc_hs;r_tpg_vs<=w_vtc_vs;r_tpg_de<=w_vtc_de;end
    end

    uitpg X_uitpg (
        .I_tpg_clk  (w_pclkx1),
        .I_tpg_rstn (w_pixel_rst_n),
        .I_tpg_vs   (w_vtc_vs),
        .I_tpg_hs   (w_vtc_hs),
        .I_tpg_de   (w_vtc_de),
        .O_tpg_vs   (),
        .O_tpg_hs   (),
        .O_tpg_de   (),
        .O_tpg_data (w_tpg_rgb)
    );

    // 摄像头实时预览：A 口 4K 流 → 抽降到 960x540 灰度 → 片内 ERAM(224 块) → 放大 2 倍显示
    cam_preview_capture #(
        .SW (960), .SH (540), .DEC_LINE (4), .DEC_CYC (1)
    ) u_cam_preview (
        .I_bc_clk    (w_a_byte_clk      ),
        .I_bc_rst_n  (w_a_rst_out       ),
        .I_pix_data  (w_a_pixel         ),
        .I_pix_valid (w_a_pixel_valid   ),
        .I_line      (w_a_in_line       ),
        .I_frame     (w_a_in_frame      ),
        .I_pclk      (w_pclkx1          ),
        .I_pclk_rst_n(w_pixel_rst_n     ),
        .I_de        (w_vtc_de          ),
        .I_vs        (w_vtc_vs          ),
        .O_rgb       (w_cam_rgb         ),
        .O_de        (w_cam_de           ),
        .O_cam_alive (w_cam_alive       ),
        .O_gray_sof(cap_sof),.O_gray_valid(cap_valid),.O_gray_last(cap_last),.O_gray_data(cap_data)
    );

    // 有摄像头画面就显示摄像头，否则显示 IP 自带测试图（方便分辨"没数据"和"没显示"）
    assign {w_rgb_r, w_rgb_g, w_rgb_b} = w_cam_alive ? w_cam_rgb : w_tpg_rgb;

    ui_HDMI_TX #(
        .DEVICE ("PH1P")
    ) X_hdmi_tx (
        .I_pixel_clk     (w_pclkx1),
        .I_serial_clk    (w_pclkx5),
        .I_rst           (~w_pll_locked),
        .I_video_in_data ({w_rgb_r, w_rgb_g, w_rgb_b}),
        .I_video_in_de   (w_cam_alive ? w_cam_de : r_tpg_de),
        .I_video_in_vs   (w_cam_alive ? r_cam_vs[1] : r_tpg_vs),
        .I_video_in_hs   (w_cam_alive ? r_cam_hs[1] : r_tpg_hs),
        .O_hdmi_clk_p    (O_hdmi_clk_p),
        .O_hdmi_tx_p     (O_hdmi_tx_p)
    );

assign cap_clk=w_a_byte_clk;
endmodule

`timescale 1ns/1ps
// Source is not backpressurable. Overflow requires an ordered ABORT token before
// any later START. Footer is a separate final word, never an untagged pixel word.
module gray_frame_pack #(parameter FRAME_BYTES=518400)(
 input clk,rst_n,sof,pixel_valid,pixel_last,input[7:0] pixel,
 output reg[257:0] out_data,output reg out_valid,input out_ready,
 output reg[31:0] dropped_frames
);
 localparam [31:0] FRAME_SIZE=FRAME_BYTES;
 reg active,abort_pending,footer_pending;reg[4:0] byte_index;
 reg[31:0] sequence_id,frame_id,byte_count,crc,final_crc;
 reg[255:0] pack_data;
 function[31:0] crc_byte(input[31:0] c,input[7:0] b);
  reg[31:0] v;integer k;begin v=c^b;for(k=0;k<8;k=k+1)v=(v>>1)^(v[0]?32'hedb88320:0);crc_byte=v;end
 endfunction
 wire[31:0] next_crc=crc_byte(crc,pixel);
 always @* begin
  out_valid=0;out_data=0;
  if(abort_pending)begin out_valid=1;out_data={2'b11,256'd0};end
  else if(footer_pending)begin out_valid=1;out_data={2'b10,128'd0,FRAME_SIZE,final_crc,frame_id,32'h43524331};end
  else if(sof&&!active)begin out_valid=1;out_data={2'b01,224'd0,sequence_id+32'd1};end
  else if(!sof&&active&&pixel_valid&&byte_index==31)begin out_valid=1;out_data={2'b00,pixel,pack_data[247:0]};end
 end
 always @(posedge clk or negedge rst_n)begin
  if(!rst_n)begin active<=0;abort_pending<=0;footer_pending<=0;byte_index<=0;
   sequence_id<=0;frame_id<=0;byte_count<=0;crc<=32'hffffffff;final_crc<=0;pack_data<=0;dropped_frames<=0;end
  else begin
   if(sof)sequence_id<=sequence_id+1'b1;
   if(abort_pending)begin
    if(out_ready)abort_pending<=0;
    if(sof)dropped_frames<=dropped_frames+1'b1;
   end else if(footer_pending)begin
    if(out_ready)footer_pending<=0;
    if(sof)dropped_frames<=dropped_frames+1'b1;
   end else if(sof)begin
    byte_index<=0;byte_count<=0;crc<=32'hffffffff;
    // Early SOF discards both the unfinished frame and the arriving frame.
    if(active)begin active<=0;abort_pending<=1;dropped_frames<=dropped_frames+32'd2;end
    else if(out_ready)begin active<=1;frame_id<=sequence_id+1'b1;end
    else begin active<=0;dropped_frames<=dropped_frames+1'b1;end
   end else if(active&&pixel_valid)begin
    pack_data[byte_index*8+:8]<=pixel;byte_index<=byte_index+1'b1;
    byte_count<=byte_count+1'b1;crc<=next_crc;
    if((byte_index==31&&!out_ready)||(pixel_last!=(byte_count==FRAME_BYTES-1)))begin
     active<=0;abort_pending<=1;dropped_frames<=dropped_frames+1'b1;
    end else if(pixel_last)begin active<=0;footer_pending<=1;final_crc<=~next_crc;end
   end
  end
 end
endmodule
